CREATE OR REPLACE FUNCTION lab.chain_of_command (p_emp numeric)
RETURNS varchar
LANGUAGE plpgsql
SET search_path = lab, public
AS $$
DECLARE
  l_chain varchar(4000);
BEGIN
  WITH RECURSIVE chain AS (
    SELECT emp_id, mgr_id, name, 1 AS lvl FROM emp WHERE emp_id = p_emp
    UNION ALL
    SELECT e.emp_id, e.mgr_id, e.name, c.lvl + 1
      FROM emp e JOIN chain c ON e.emp_id = c.mgr_id
  )
  SELECT string_agg(name, ' > ' ORDER BY lvl DESC INTO STRICT l_chain FROM chain;
  RETURN l_chain;
END;
$$;

